UPDATE profile SET
  about_es = 'Estoy en DAM y no me quedo en los apuntes. Meto mano en Android, en multiplataforma y en entornos ERP; cuando hay un problema real, intento llevarlo de la idea a algo que se pueda usar. Me gusta construir cosas completas —webs, paneles, apps— y verlas funcionar fuera del aula.

Soy ambicioso: quiero crecer rápido, asumir más de lo “justo para aprobar” y despegar como desarrollador de software. Busco un equipo exigente donde aportar de verdad, aprender cada semana y, si encaja, hacerlo también fuera de España.',
  about_en = 'I’m in DAM and I don’t stop at notes. I get hands-on with Android, multiplatform work and ERP environments; when there’s a real problem, I try to take it from idea to something people can actually use. I like building complete things—webs, panels, apps—and seeing them work outside the classroom.

I’m ambitious: I want to grow fast, take on more than “just enough to pass,” and take off as a software developer. I’m looking for a demanding team where I can contribute for real, learn every week and, if it fits, do that outside Spain too.',
  updated_at = datetime('now')
WHERE id = 1;
